using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.TKT.ComentariosTicket;namespace GraphApi.Services.TKT.ComentariosTicket{    public class ComentariosTicketService : IComentariosTicketService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public ComentariosTicketService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadComentariosTicket>> GetComentariosTickets(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM tkt.ComentariosTicket (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadComentariosTicket>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetComentariosTicketsDynamic(            int? comentarioTicketID,            int? ticketID,            int? usuarioID,            string? comentario,            DateTime? fechaComentario,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "ComentarioTicketID, TicketID, UsuarioID, Comentario, FechaComentario, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM tkt.ComentariosTicket (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (comentarioTicketID.HasValue)            {                vSql.Append(" AND ComentarioTicketID = @ComentarioTicketID");                vParameters.Add("ComentarioTicketID",comentarioTicketID);            }            if (!string.IsNullOrWhiteSpace(comentario))            {                vSql.Append(" AND Comentario LIKE @Comentario");                vParameters.Add("Comentario",$"%{comentario}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadComentariosTicket> CreateComentariosTicket(clCreateComentariosTicket objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO tkt.ComentariosTicket                (TicketID, UsuarioID, Comentario, FechaComentario, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TicketID, @UsuarioID, @Comentario, @FechaComentario, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TicketID,                objInput.UsuarioID,                objInput.Comentario,                objInput.FechaComentario,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT ComentarioTicketID, TicketID, UsuarioID, Comentario, FechaComentario, bEliminado                FROM tkt.ComentariosTicket (NOLOCK)                WHERE ComentarioTicketID = @ComentarioTicketID;";            var vReadParams = new { ComentarioTicketID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadComentariosTicket>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el ComentariosTicket con ID {vNewId}.");            return vCreated;        }        public async Task<clReadComentariosTicket?> UpdateComentariosTicket(clUpdateComentariosTicket objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("ComentarioTicketID", objInput.ComentarioTicketID);            if (objInput.TicketID != null)            {                vSets.Add("TicketID = @TicketID");                vParameters.Add("TicketID", objInput.TicketID);            }            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.Comentario is not null)            {                vSets.Add("Comentario = @Comentario");                vParameters.Add("Comentario", objInput.Comentario);            }            if (objInput.FechaComentario != null)            {                vSets.Add("FechaComentario = @FechaComentario");                vParameters.Add("FechaComentario", objInput.FechaComentario);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE tkt.ComentariosTicket                SET {vSetClause}                WHERE ComentarioTicketID = @ComentarioTicketID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT ComentarioTicketID, TicketID, UsuarioID, Comentario, FechaComentario, bEliminado                FROM tkt.ComentariosTicket (NOLOCK)                WHERE ComentarioTicketID = @ComentarioTicketID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadComentariosTicket>(sSelect, new {  objInput.ComentarioTicketID });        }        public async Task<bool> DeleteComentariosTicket(int nComentariosTicketID)        {            const string sSql = @"                DELETE FROM tkt.ComentariosTicket                WHERE ComentarioTicketID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nComentariosTicketID });            return vAffected > 0;        }    }}